right:
@import 'c/rlySharedStyles';

:host {
    padding-bottom: 1.5rem;
    display: block;
    --rr-blue: #0176d3;
    --rr-link: #0b5cab;
    --rr-ink: #181818;
    --rr-muted: #5c5c5c;
    --rr-line: #e5e5e5;
    --rr-ok: #2e844a;
    --rr-bad: #ba0517;
    --rr-warn: #dd7a01;
}

.rr-page { display: flex; flex-direction: column; gap: 12px; color: var(--rr-ink); min-height: 160px; }
.rr-page p { margin: 0; }
.rr-card { background: #fff; border: 1px solid var(--rr-line); border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); min-width: 0; }
.rr-grow { flex: 1 1 auto; min-width: 0; }
.rr-tiny { font-size: 11px; }
.rr-pad { padding: 12px 16px; }
.rr-msg { padding: 8px 10px; border-radius: 4px; font-size: 12px; line-height: 1.45; }
.rr-msg-warn { background: #fef1cd; color: #5c3a00; }
.rr-freeze { margin-bottom: 8px; }
.rr-link, .rr-linkbtn { border: 0; background: none; padding: 0; font: inherit; font-size: 12px; color: var(--rr-link); cursor: pointer; white-space: nowrap; }
.rr-linkbtn { text-decoration: underline; }
.rr-link:hover { text-decoration: underline; }
.rr-link:focus-visible, .rr-linkbtn:focus-visible, .rr-rel:focus-visible, .rr-open:focus-visible, .rr-chip:focus-visible, .rr-tile-btn:focus-visible {
    outline: 2px solid var(--rr-blue); outline-offset: 2px;
}

/* header (as the other tabs: rlyReleaseTracker .rr-head) */
.rr-head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 12px 16px; }
.rr-title { margin: 0; font-size: 18px; font-weight: 700; }
.rr-greet { margin-top: 2px; font-size: 13px; }
.rr-greet-need { color: #8c4b02; }
.rr-head-actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* health line */
.rr-hs { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 16px; padding: 8px 16px; font-size: 12px; }
.rr-hs-title { font-size: 11px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--rr-muted); }
.rr-hs-full { display: contents; }
.rr-hs-short { display: none; }
.rr-hs-item { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.rr-hs-att { color: #8c4b02; font-weight: 700; }
.rr-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex: none; }
.rr-dot-ok { background: var(--rr-ok); }
.rr-dot-bad { background: var(--rr-bad); }
.rr-dot-wait { background: var(--rr-warn); }
.rr-dot-none { background: #939393; }

/* KPI tiles */
.rr-kpis { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 12px; }
.rr-tile {
    position: relative; display: flex; flex-direction: column; gap: 2px; min-width: 0; padding: 10px 14px; text-align: left;
    background: #fff; border: 1px solid var(--rr-line); border-top: 3px solid var(--rr-line); border-radius: 4px;
    box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); font: inherit; color: var(--rr-ink);
}
.rr-tile-btn { cursor: pointer; }
.rr-tile-btn:hover { border-color: var(--rr-blue); box-shadow: 0 0 0 1px var(--rr-blue); }
.rr-tile-warn { border-top-color: var(--rr-warn); }
.rr-tile-alarm { border-top-color: var(--rr-bad); }
.rr-tile-good { border-top-color: var(--rr-ok); }
.rr-tile-label, .rr-tile-sub { display: block; font-size: 12px; color: var(--rr-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding-right: 12px; }
/* a label that doesn't fit wraps to a second line (never cut off); the value and sub line stay level across the row */
.rr-tile-label { white-space: normal; overflow-wrap: anywhere; text-overflow: clip; line-height: 1.3; max-height: 2.6em; }
.rr-tile-sub { min-height: 18px; }
.rr-tile-value { display: flex; align-items: baseline; gap: 6px; margin-top: auto; font-size: 28px; font-weight: 300; line-height: 1.15; }
.rr-tile-value small { font-size: 13px; font-weight: 400; color: var(--rr-muted); }
.rr-tile-go { position: absolute; right: 10px; top: 8px; color: #939393; font-size: 13px; }

/* rows */
/* the chart's column keeps at least 380px, so its SVG text (scaled with the viewBox) stays 11px or larger */
.rr-row2 { display: grid; grid-template-columns: minmax(0, 2fr) minmax(380px, 1fr); gap: 12px; align-items: start; }
.rr-card-hd { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; min-height: 32px; padding: 10px 12px 10px 16px; border-bottom: 1px solid var(--rr-line); }
.rr-cap { margin: 6px 0 2px; font-size: 11px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--rr-muted); }
.rr-pill { display: inline-flex; align-items: center; height: 20px; padding: 0 8px; border-radius: 10px; font-size: 11px; font-weight: 700; white-space: nowrap; vertical-align: middle; }
.rr-lfoot { display: flex; align-items: center; gap: 8px; padding: 7px 16px; border-top: 1px solid var(--rr-line); font-size: 12px; color: var(--rr-muted); }
.rr-empty {
    display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 18px; text-align: center; font-size: 13px;
    color: var(--rr-muted); background: #fafaf9; border: 1px dashed #c9c9c9; border-radius: 4px;
}
.rr-empty b { color: var(--rr-ink); }

/* ---- long lists (build 27, same in every bundle): search toolbar, fixed columns, pinned header, scroll inside ---- */
.rr-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 8px 12px; border-bottom: 1px solid var(--rr-line); }
.rr-scroll { max-height: 26rem; overflow: auto; }
.rr-scroll-needs { height: 300px; max-height: 300px; }
.rr-scroll-activity { height: 373px; max-height: 373px; }
.rr-ft { width: 100%; table-layout: fixed; border-collapse: separate; border-spacing: 0; font-size: 13px; }
.rr-ft th {
    position: sticky; top: 0; z-index: 2; height: 31px; padding: 0 8px; background: #f3f3f3; color: #444; font-size: 12px; font-weight: 700;
    text-align: left; border-bottom: 1px solid var(--rr-line); box-sizing: border-box;
}
.rr-ft th, .rr-ft td { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-ft td { height: 38px; padding: 0 8px; border-bottom: 1px solid #f3f3f3; vertical-align: middle; box-sizing: border-box; }
.rr-ft th:first-child, .rr-ft td:first-child { padding-left: 16px; }
.rr-ft .rr-c { text-align: center; padding: 0; }
.rr-ft .rr-r { text-align: right; }
.rr-ft tr.rr-gh td {
    position: sticky; top: 31px; z-index: 1; height: 27px; background: #fafaf9; color: var(--rr-muted); font-size: 11px; font-weight: 700;
    letter-spacing: 0.04em; text-transform: uppercase; border-bottom: 1px solid var(--rr-line);
}
.rr-ft tr.rr-gh em { margin-left: 6px; font-style: normal; font-weight: 400; letter-spacing: 0; text-transform: none; }
.rr-ft td.rr-group-empty, .rr-ft td.rr-nomatch { height: auto; padding: 14px 16px; white-space: normal; text-align: center; color: var(--rr-muted); }
.rr-ft td.rr-group-empty b { color: var(--rr-ink); }
.rr-ft .rr-line { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; line-height: 1.3; }
.rr-ft .rr-sub { font-size: 12px; color: var(--rr-muted); }
.rr-ft mark, .rr-scroll mark { background: #fce38a; color: inherit; padding: 0 1px; border-radius: 2px; }
.rr-ft tbody tr:hover td { background: #f3f7fd; }
.rr-ft tbody tr.rr-gh:hover td { background: #fafaf9; }
.rr-ft-small { font-size: 12px; }
.rr-ft-small td { height: 28px; }
.rr-rel { border: 0; background: none; padding: 0; font: inherit; font-weight: 700; color: var(--rr-link); cursor: pointer; text-align: left; max-width: 100%; }
.rr-rel:hover { text-decoration: underline; }
.rr-open { height: 24px; padding: 0 9px; border: 1px solid #c9c9c9; border-radius: 4px; background: #fff; color: var(--rr-link); font: inherit; font-size: 12px; cursor: pointer; }
.rr-open:hover { background: #f3f3f3; }
.rr-w-34 { width: 34px; }
.rr-w-40 { width: 40px; }
.rr-w-60 { width: 60px; }
.rr-w-62 { width: 62px; }
.rr-w-64 { width: 64px; }
.rr-w-72 { width: 72px; }
.rr-w-96 { width: 96px; }
.rr-w-100 { width: 100px; }
.rr-w-108 { width: 108px; }
.rr-w-112 { width: 112px; }
.rr-w-136 { width: 136px; }
.rr-w-156 { width: 156px; }
.rr-ic { width: 22px; height: 22px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; vertical-align: middle; }
.rr-ic-G { background: #ebf7e6; --slds-c-icon-color-foreground-default: #2e844a; }
.rr-ic-R { background: #feded8; --slds-c-icon-color-foreground-default: #8e030f; }
.rr-ic-B { background: #eef4ff; --slds-c-icon-color-foreground-default: #014486; }
.rr-ic-A { background: #fef1cd; --slds-c-icon-color-foreground-default: #8c4b02; }
.rr-ic-N { background: #f3f3f3; --slds-c-icon-color-foreground-default: #444; }

/* activity chips */
.rr-chips { display: flex; gap: 6px; flex-wrap: nowrap; overflow-x: auto; }
.rr-chip {
    display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 10px; border: 1px solid #c9c9c9; border-radius: 14px;
    background: #fff; color: var(--rr-ink); font: inherit; font-size: 12px; white-space: nowrap; cursor: pointer;
}
.rr-chip i { font-style: normal; font-size: 11px; font-weight: 700; padding: 1px 6px; border-radius: 8px; background: #f3f3f3; color: #444; }
.rr-chip-on { background: var(--rr-blue); border-color: var(--rr-blue); color: #fff; }
.rr-chip-on i { background: #fff; color: #014486; }

/* chart */
.rr-chart { display: flex; flex-direction: column; gap: 6px; padding: 10px 16px 12px; }
.rr-legend { display: flex; gap: 14px; align-items: center; font-size: 12px; color: #444; }
.rr-legend i { display: inline-block; width: 10px; height: 10px; margin-right: 5px; border-radius: 2px; vertical-align: -1px; }
.rr-key-ok { background: var(--rr-ok); }
.rr-key-bad { background: var(--rr-bad); }
.rr-chart-svg { display: block; width: 100%; height: auto; }
.rr-gridline { stroke: #f3f3f3; stroke-width: 1; }
.rr-baseline { stroke: #c9c9c9; stroke-width: 1; }
/* SVG text sizes are viewBox units (420 wide): 13.5 units render at 11px or more whenever the chart column is 380px or wider */
.rr-axis { font-size: 13.5px; fill: #5c5c5c; text-anchor: end; }
.rr-bar-ok { fill: var(--rr-ok); }
.rr-bar-bad { fill: var(--rr-bad); }
.rr-chart-wk { font-size: 13.5px; fill: var(--rr-muted); text-anchor: middle; }
.rr-chart-now { font-size: 13.5px; font-weight: 700; fill: var(--rr-ink); text-anchor: middle; }
.rr-peak { font-size: 13.5px; font-weight: 700; fill: var(--rr-ok); text-anchor: middle; }
.rr-chart-foot { display: flex; gap: 16px; align-items: center; padding-top: 6px; border-top: 1px solid #f3f3f3; font-size: 12px; color: var(--rr-muted); }
.rr-chart-foot b { color: var(--rr-ink); }

/* route */
.rr-route { display: flex; align-items: stretch; padding: 12px 16px 14px; }
.rr-stop-wrap { display: flex; flex: 1 1 0; min-width: 0; align-items: stretch; }
.rr-stop { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; background: #fff; border: 1px solid var(--rr-line); border-radius: 4px; }
.rr-stop-hub { border-color: #b0c9f5; }
.rr-stop-hd { display: flex; align-items: center; gap: 8px; padding: 8px 12px; background: #fafaf9; border-bottom: 1px solid #f3f3f3; border-radius: 4px 4px 0 0; }
.rr-stop-hub .rr-stop-hd { background: #eef4ff; }
.rr-stop-hd b { font-size: 15px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rr-stop-st { margin-left: auto; display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: #444; white-space: nowrap; }
.rr-stop-bd { flex: 1; display: flex; flex-direction: column; gap: 8px; padding: 8px 12px 10px; font-size: 12px; }
.rr-stop-last { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.rr-stop-last .rr-line { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-stop-last .rr-rel { font-size: 13px; color: var(--rr-ink); }
.rr-stop-count { display: flex; align-items: center; gap: 8px; margin-top: auto; padding-top: 8px; border-top: 1px solid #f3f3f3; }
.rr-stop-n { font-size: 22px; font-weight: 300; line-height: 1; }
.rr-stop-text { color: #444; line-height: 1.3; }
.rr-arrow { flex: 0 0 28px; display: flex; align-items: center; justify-content: center; color: var(--rr-blue); font-size: 18px; font-weight: 700; }
.rr-arrow-down { display: none; }

/* narrow (board HubHome D): one column, tiles 2 per row, route top to bottom, health in one line */
@media (max-width: 899px) {
    .rr-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
    .rr-tile-value { font-size: 22px; }
    .rr-row2 { grid-template-columns: minmax(0, 1fr); }
    .rr-hide-narrow { display: none; }
    .rr-hs-full { display: none; }
    .rr-hs-short { display: inline-flex; }
    .rr-head-actions, .rr-new { width: 100%; }
    .rr-toolbar c-rly-search-box { flex-basis: 100%; }
    .rr-chips { width: 100%; }
    .rr-ft td { height: 48px; }
    .rr-ft th:first-child, .rr-ft td:first-child { padding-left: 10px; }
    .rr-scroll-needs { height: 250px; max-height: 60vh; }
    .rr-scroll-activity { height: 240px; max-height: 60vh; }
    .rr-route { flex-direction: column; }
    .rr-stop-wrap { flex-direction: column; flex: none; }
    .rr-arrow { flex: none; height: 22px; }
    .rr-arrow-right { display: none; }
    .rr-arrow-down { display: inline; }
}
